(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.35)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w2 = Math.cos(x*0.025-y*0.01+t*0.28)*8 + Math.sin(y*0.022+x*0.008-t*0.4)*6;
  const w3 = Math.sin((x+y)*0.008+t*0.15)*10;
  const sx = x + w1 + w3, sy = y + w2 + w3;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 1.3],
    [340+Math.cos(t*0.45)*95, 150+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 110+Math.cos(t*0.42+1)*85, 0.055, 2.4, 1.5],
    [90+Math.cos(t*0.7+1)*75, 190+Math.sin(t*0.5+3)*55, 0.11, 1.4, 0.7],
    [380+Math.sin(t*0.38+4)*85, 55+Math.cos(t*0.82+2)*65, 0.065, 2.7, 1.1],
    [200+Math.cos(t*0.32+5)*100, 210+Math.sin(t*0.48)*70, 0.085, 1.95, 1.0],
