  let act=0, inh=0, pulse=0, twist=0;
  for (const [sX,sY,f,sp,amp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const ang = Math.atan2(sy-sY, sx-sX);
    act += Math.sin(d*f - t*sp) * amp;
    inh += Math.sin(d*f*0.72 + t*sp*0.55 + 1.7) * amp * 0.85;
    pulse += Math.exp(-d*0.008)*Math.sin(d*0.15 - t*sp*1.3)*0.6;
    twist += Math.sin(d*0.04 - ang*2 + t*0.8)*Math.exp(-d*0.005)*0.5;
  }
  act/=8; inh/=8; pulse/=8; twist/=8;
  const bg1 = Math.sin(sx*0.035+sy*0.028+t*0.7) + Math.sin(sx*0.025-sy*0.038+t*0.95);
