  const lap = Math.sin(sx*0.16)*Math.sin(sy*0.16)+Math.sin((sx+sy)*0.11+t*0.8)*0.4+Math.sin((sx-sy)*0.09-t*0.6)*0.3;
  const cell = Math.tanh(lap*1.8)*0.35;
  const cross = Math.tanh(act*inh*2.5)*0.2;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.28 + spiral + pulse*0.4 + twist*0.3)*2.0);
  const blend = reaction*0.6 + cell*0.22 + cross*0.18;
  const v = blend*0.5+0.5;
  const detail = Math.sin(blend*8+t*0.5)*0.04;
  const vf = Math.max(0, Math.min(1, v+detail));
  const pal = [[6,12,52],[12,45,88],[18,95,120],[28,148,138],[80,175,140],[180,195,90],[220,175,60],[215,125,65],[185,70,72],[120,35,65],[55,18,55],[6,12,52]];
